result={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'protocol_sha256':sha((folder/'protocol.json').read_bytes()),'records':rows,'matched':sum(r['matched'] for r in rows),'cases':len(rows),'source_executed':False,'model_calls':0,'production_modified':False,'independent_accuracy_metric':None};(folder/'results.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items() if k!='records'}));print(json.dumps([{'id':r['id'],'status':r['packet']['status'],'qualified':[q['import_path']+':'+q['name'] for q in r['packet']['qualified_uses']],'selections':r['packet']['selections'],'diagnostics':r['packet']['diagnostics'],'matched':r['matched']} for r in rows]));assert all(r['matched'] for r in rows)
